@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Duolingo DNA — bright green, chunky 3D-pressed buttons, very rounded, cheerful */
.theme-duolingo-dna {
  --bg: oklch(1 0 0);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.965 0.02 150);
  --fg: oklch(0.3 0.02 250);
  --fg-muted: oklch(0.58 0.02 250);
  --accent: oklch(0.636 0.229 137.6);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.718 0.151 237.1);
  --line: oklch(0.88 0.01 250);
  --success: oklch(0.75 0.21 140);
  --warning: oklch(0.82 0.17 80);
  --danger: oklch(0.63 0.22 25);

  --radius: 1rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.5rem;
  --radius-pill: 9999px;

  --shadow-1: 0 3px 0 0 oklch(0.85 0.01 250);
  --shadow-2: 0 4px 0 0 oklch(0.62 0.19 140);
  --shadow-3: 0 6px 0 0 oklch(0.8 0.01 250);
  --glow: 0 0 0 4px color-mix(in oklab, var(--accent) 35%, transparent);

  --border-width: 2px;
  --blur-amount: 0px;

  --font-display: "Baloo 2", sans-serif;
  --font-body: "Baloo 2", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.015em;
  --label-transform: uppercase;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-duolingo-dna h1,
.theme-duolingo-dna h2,
.theme-duolingo-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 800;
}

.theme-duolingo-dna button {
  border-radius: var(--radius);
  font-weight: 800;
  border-bottom-width: 4px;
  border-bottom-style: solid;
  border-bottom-color: oklch(0 0 0 / 18%);
  transition: transform 80ms ease, border-bottom-width 80ms ease;
}

.theme-duolingo-dna button:active {
  transform: translateY(3px);
  border-bottom-width: 1px;
}

/* signature */
.theme-duolingo-dna { --font-ui: var(--font-display); }
.theme-duolingo-dna h1 { font-weight: 800; }
.theme-duolingo-dna button { border-bottom: 4px solid color-mix(in oklab, var(--accent) 65%, black); font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; }
.theme-duolingo-dna button:active { transform: translateY(3px); border-bottom-width: 1px; }

/* depth */
.theme-duolingo-dna thead th { font-size: 0.72rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; color: var(--fg-muted); border-bottom: 2px solid var(--line); }
.theme-duolingo-dna td { border-bottom: 2px solid var(--surface-2); }
.theme-duolingo-dna input, .theme-duolingo-dna select, .theme-duolingo-dna textarea { border: 2px solid var(--line); border-radius: var(--radius); background: var(--surface); transition: border-color 100ms ease, box-shadow 100ms ease; }
.theme-duolingo-dna input:focus-visible, .theme-duolingo-dna select:focus-visible, .theme-duolingo-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-duolingo-dna a { color: var(--accent-2); font-weight: 800; text-decoration: none; }
.theme-duolingo-dna a:hover { text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 2px; }
.theme-duolingo-dna ::selection { background: color-mix(in oklab, var(--accent) 30%, white); }
.theme-duolingo-dna ::-webkit-scrollbar { width: 12px; }
.theme-duolingo-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-duolingo-dna ::-webkit-scrollbar-thumb { background: var(--line); border-radius: 999px; border: 3px solid var(--bg); }
.theme-duolingo-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-duolingo-dna kbd { font-weight: 700; font-size: 0.75em; background: var(--surface-2); border: 2px solid var(--line); border-bottom-width: 4px; border-radius: 0.6em; padding: 0.05em 0.45em; }
.theme-duolingo-dna .label-caps { font-weight: 800; color: var(--fg-muted); }
.theme-duolingo-dna .themed-border { border-color: var(--line); border-width: 2px; }
.theme-duolingo-dna button:hover { filter: brightness(1.06); }

/* alt mode: Duolingo dark — the real app night palette, owl-green intact */
.theme-duolingo-dna.alt-mode {
  --bg: oklch(0.215 0.020 235.0);
  --surface: oklch(0.255 0.022 235.0);
  --surface-2: oklch(0.300 0.024 235.0);
  --fg: oklch(0.955 0.010 220);
  --fg-muted: oklch(0.68 0.020 225);
  --line: oklch(0.375 0.025 235);
  --shadow-1: 0 3px 0 0 oklch(0.14 0.015 235);
  --shadow-2: 0 4px 0 0 oklch(0.50 0.16 140);
  --shadow-3: 0 6px 0 0 oklch(0.14 0.015 235);
}
.theme-duolingo-dna.alt-mode ::selection { background: oklch(0.45 0.13 140); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
